          "summary": "据 The Information 报道并由 36 氪转述，谷歌正在研发代号 Frozen v2 的 Gemini 专用服务器芯片，把模型架构直接固化到硅片中，目标是在推理效率上达到现有自研芯片的 6 至 10 倍。",
